// Auto-expire custom orders past validity
export async function autoExpirePendingCustomOrders(): Promise<void> {
  try {
    const awaitingOrders = await (prisma as any).customOrder.findMany({
      where: { paymentStatus: 'AWAITING_PAYMENT' }
    });

    const now = Date.now();
    const expiredOrders = (awaitingOrders || []).filter(
      (ord: any) => ord?.expiresAt && new Date(ord.expiresAt).getTime() <= now
    );

    if (expiredOrders.length === 0) return;

    for (const ord of expiredOrders) {
      if (ord.razorpayQrId) {
        deactivateRazorpayQrCode(ord.razorpayQrId).catch(() => {});
      }
    }

    const expiredIds = expiredOrders.map((ord: any) => ord.id);
    await (prisma as any).customOrder.updateMany({
      where: { id: { in: expiredIds } },
      data: {
        paymentStatus: 'EXPIRED',
        updatedAt: new Date().toISOString()
      }
    });
  } catch (err) {
    console.warn('Auto-expire custom orders check warning:', err);
  }
}

// Admin Analytics
app.get('/api/admin/analytics', requireAdminMiddleware, async (req: Request, res: Response) => {
  try {
    await autoExpirePendingCustomOrders();

    const totalOrders = await prisma.order.count();
    const totalProducts = await prisma.product.count();
    const totalUsers = await prisma.user.count();
    const totalQuotes = await prisma.quoteRequest.count();
    const totalCustomers = totalUsers;

    const orders = await prisma.order.findMany({
      include: { items: { include: { product: true } } }
    });

    const totalRevenue = orders.reduce((sum, o) => sum + Number(o.totalAmount || 0), 0);
    const averageOrderValue = totalOrders > 0 ? Math.round(totalRevenue / totalOrders) : 0;

    // Custom Orders (QR) Analytics - Kept strictly separate from Direct Orders
    const customOrders = await (prisma as any).customOrder.findMany({
      orderBy: { createdAt: 'desc' }
    });
    const totalCustomOrders = customOrders.length;
    const paidCustomOrders = customOrders.filter((co: any) => co.paymentStatus === 'PAID');
    const customOrdersPaidCount = paidCustomOrders.length;
    // Business rule: "Custom Order Revenue" includes Paid/Completed orders, but excludes Awaiting Payment, Cancelled/Expired, and Deleted orders.
    const customOrdersRevenue = paidCustomOrders.reduce((sum: number, co: any) => sum + Number(co.amount || 0), 0);
    const customOrdersAwaitingCount = customOrders.filter((co: any) => co.paymentStatus === 'AWAITING_PAYMENT').length;
    const customOrdersCancelledCount = customOrders.filter((co: any) => co.paymentStatus === 'CANCELLED' || co.paymentStatus === 'EXPIRED').length;

    // 7 days revenue trend
    const days: { [date: string]: { date: string; revenue: number; orders: number } } = {};
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      days[dateStr] = { date: dateStr, revenue: 0, orders: 0 };
    }

    orders.forEach((o) => {
      const dateStr = new Date(o.createdAt).toISOString().split('T')[0];
      if (days[dateStr]) {
        days[dateStr].revenue += Number(o.totalAmount || 0);
        days[dateStr].orders += 1;
      }
    });

    const revenueByDay = Object.values(days);

    // Category breakdown
    const categories = await prisma.category.findMany();
    const catMap: { [id: string]: { name: string; revenue: number } } = {};
    categories.forEach((c) => { catMap[c.id] = { name: c.name, revenue: 0 }; });

    orders.forEach((o) => {
      o.items.forEach((item) => {
        if (item.product?.categoryId && catMap[item.product.categoryId]) {
          catMap[item.product.categoryId].revenue += Number(item.total || 0);
        }
      });
    });

    const catList = Object.values(catMap);
    const totalCatRev = catList.reduce((sum, c) => sum + c.revenue, 0) || 1;
    const categoryBreakdown = catList.map((c) => ({
      categoryName: c.name,
      revenue: c.revenue,
      percentage: Math.round((c.revenue / totalCatRev) * 100)
    }));

    // Top selling products
    const prodMap: { [id: string]: { productId: string; title: string; quantitySold: number; totalRevenue: number } } = {};
    orders.forEach((o) => {
      o.items.forEach((item) => {
        if (item.productId) {
          if (!prodMap[item.productId]) {
            prodMap[item.productId] = {
              productId: item.productId,
              title: item.productTitle || item.product?.name || 'Product',
              quantitySold: 0,
              totalRevenue: 0
            };
          }
          prodMap[item.productId].quantitySold += item.quantity;
          prodMap[item.productId].totalRevenue += Number(item.total || 0);
        }
      });
    });

    const topSellingProducts = Object.values(prodMap)
      .sort((a, b) => b.totalRevenue - a.totalRevenue)
      .slice(0, 5);

    return res.json({
      totalOrders,
      totalProducts,
      totalUsers,
      totalCustomers,
      totalQuotes,
      totalRevenue,
      averageOrderValue,
      revenueByDay,
      categoryBreakdown,
      topSellingProducts,
      recentOrders: orders.slice(0, 5),
      customOrdersRevenue,
      customOrdersPaidCount,
      totalCustomOrders,
      customOrdersAwaitingCount,
      customOrdersCancelledCount
    });
  } catch (err: any) {
    return res.status(500).json({ error: 'Failed to fetch analytics' });
  }
});

