app.post('/api/products/:id/reviews', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { rating, title, comment, userName } = req.body;

    let userId: string | null = null;
    let reviewerName = userName || 'Verified Customer';

    let guestUser: any = null;
    const token = req.cookies?.token || (req.headers.authorization?.startsWith('Bearer ') ? req.headers.authorization.split(' ')[1] : null);
    if (token && !isTokenRevoked(token)) {
      try {
        const decoded = jwt.verify(token, JWT_SECRET) as any;
        if (decoded?.id) {
          userId = decoded.id;
          if (!userName && decoded.name) reviewerName = decoded.name;
        }
      } catch (e) {
        // Proceed as guest
      }
    }

    if (!userId) {
      guestUser = await prisma.user.findFirst({
        where: { email: 'guest@nexra3d.com' }
      });
      if (!guestUser) {
        guestUser = await prisma.user.create({
          data: {
            email: 'guest@nexra3d.com',
            password: 'guest_password_protected_review_account',
            name: 'Guest Customer',
            role: 'CUSTOMER'
          }
        });
      }
      userId = guestUser.id;
    }

    // Determine if reviewer has a verified purchase for this product
    let isVerifiedPurchase = false;
    if (userId && (!guestUser || userId !== guestUser.id)) {
      const purchase = await prisma.orderItem.findFirst({
        where: {
          productId: id,
          order: {
            userId: userId,
            paymentStatus: 'PAID'
          }
        }
      });
      isVerifiedPurchase = Boolean(purchase);
    }

    const review = await prisma.review.create({
      data: {
        productId: id,
        userId: userId,
        userName: reviewerName,
        rating: Number(rating || 5),
        title: title || 'Customer Review',
        comment: comment || '',
        verifiedPurchase: isVerifiedPurchase
      }
    });

    invalidateProductListCache();
    return res.status(201).json({ success: true, review });
  } catch (err: any) {
    console.error('Failed to create review:', err);
    return res.status(500).json({ error: 'Failed to create review' });
  }
});

