// 7. Delete Expired or Cancelled Custom Order (Admin)
// Releases the order sequence number for reuse
app.delete('/api/admin/custom-orders/:id', requireAdminMiddleware, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const order = await (prisma as any).customOrder.findUnique({ where: { id } });
    if (!order) {
      return res.status(404).json({ error: 'Custom order not found' });
    }

    const isPastExpiry = order.expiresAt && new Date(order.expiresAt).getTime() <= Date.now();
    const isCancelledOrExpired = order.paymentStatus === 'CANCELLED' || order.paymentStatus === 'EXPIRED' || isPastExpiry;

    if (!isCancelledOrExpired) {
      if (order.paymentStatus === 'PAID') {
        return res.status(400).json({
          error: 'Paid custom orders cannot be deleted as they represent settled financial transactions.'
        });
      }
      return res.status(400).json({
        error: 'Active custom order cannot be deleted. Deactivate or expire the QR code first.'
      });
    }

    // Deactivate in Razorpay if still active
    if (order.razorpayQrId) {
      await deactivateRazorpayQrCode(order.razorpayQrId).catch(() => {});
    }

    await (prisma as any).customOrder.delete({
      where: { id }
    });

    return res.json({
      success: true,
      message: `Custom order ${id} deleted successfully. Its sequence number has been released for reuse.`
    });
  } catch (err: any) {
    console.error('Error deleting custom order:', err);
    return res.status(500).json({ error: err.message || 'Failed to delete custom order' });
  }
});

// 8. Update Custom Order Showcase Details & Order Info (Admin)
app.patch('/api/admin/custom-orders/:id', requireAdminMiddleware, async (req: Request, res: Response) => {
  try {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
    const { id } = req.params;
    const {
      customOrderName,
      imageUrl,
      isPublic,
      customerName,
      phone,
      email,
      description,
      amount,
      deliveryType,
      notes,
      paymentStatus
    } = req.body;

    const cleanId = String(id || '').trim();
    let existing = await (prisma as any).customOrder.findUnique({ where: { id: cleanId } });
    if (!existing) {
      existing = await (prisma as any).customOrder.findFirst({
        where: {
          id: {
            equals: cleanId,
            mode: 'insensitive'
          }
        }
      });
    }

    const nowIso = new Date().toISOString();
    const updateData: any = {
      updatedAt: nowIso
    };
    if (customOrderName !== undefined) {
      updateData.customOrderName = customOrderName ? String(customOrderName).trim() : null;
    }
    if (imageUrl !== undefined) {
      updateData.imageUrl = imageUrl ? String(imageUrl).trim() : null;
    }
    if (isPublic !== undefined) {
      updateData.isPublic = Boolean(isPublic);
    }
    if (customerName !== undefined && String(customerName).trim()) {
      updateData.customerName = String(customerName).trim();
    }
    if (phone !== undefined && String(phone).trim()) {
      updateData.phone = String(phone).trim();
    }
    if (email !== undefined) {
      updateData.email = email ? String(email).trim() : null;
    }
    if (description !== undefined) {
      updateData.description = description ? String(description).trim() : null;
    }
    if (amount !== undefined && !isNaN(Number(amount)) && Number(amount) >= 0) {
      updateData.amount = Number(amount);
    }
    if (deliveryType !== undefined && (deliveryType === 'STORE_PICKUP' || deliveryType === 'HOME_DELIVERY')) {
      updateData.deliveryType = deliveryType;
    }
    if (notes !== undefined) {
      updateData.notes = notes ? String(notes).trim() : null;
    }
    if (paymentStatus !== undefined && typeof paymentStatus === 'string' && paymentStatus.trim()) {
      const statusUpper = paymentStatus.trim().toUpperCase();
      updateData.paymentStatus = statusUpper;
      if (statusUpper === 'PAID') {
        updateData.paidAt = existing?.paidAt || nowIso;
      } else if (statusUpper === 'AWAITING_PAYMENT') {
        // Protect from autoExpirePendingCustomOrders immediately flipping it back to EXPIRED
        if (!existing?.expiresAt || new Date(existing.expiresAt).getTime() <= Date.now()) {
          updateData.expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
        }
      }
    }

    const targetId = existing?.id || cleanId;
    let updated;
    if (existing) {
      updated = await (prisma as any).customOrder.update({
        where: { id: targetId },
        data: updateData
      });
    } else {
      const initialStatus = paymentStatus ? String(paymentStatus).toUpperCase() : 'PAID';
      const futureExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
      updated = await (prisma as any).customOrder.upsert({
        where: { id: cleanId },
        create: {
          id: cleanId,
          customerName: customerName || 'Valued Customer',
          phone: phone || '',
          email: email || null,
          description: description || customOrderName || 'Custom Order',
          customOrderName: customOrderName || null,
          imageUrl: imageUrl || null,
          isPublic: isPublic !== undefined ? Boolean(isPublic) : false,
          amount: amount !== undefined ? Number(amount) : 0,
          deliveryType: deliveryType || 'STORE_PICKUP',
          notes: notes || null,
          paymentStatus: initialStatus,
          expiresAt: initialStatus === 'AWAITING_PAYMENT' ? futureExpiry : null,
          paidAt: initialStatus === 'PAID' ? nowIso : null,
          createdAt: req.body.createdAt || nowIso,
          updatedAt: nowIso
        },
        update: updateData
      });
    }

    return res.json({
      customOrder: updated,
      message: 'Custom order updated successfully.'
    });
  } catch (err: any) {
    console.error('Error updating custom order:', err);
    return res.status(500).json({ error: err.message || 'Failed to update custom order' });
  }
});

